const analisis = $('Leer analisis_actual').first().json;
const priceData = $('Obtener Velas 1H Twelve Data').first().json;

if (!analisis || !analisis.tipo_zona || analisis.precio_zona_suelo === 0) {
  throw new Error('No hay zona activa para registrar hoy');
}

const values = priceData?.values || [];
const precio_suelo = parseFloat(analisis.precio_zona_suelo);
const precio_techo = parseFloat(analisis.precio_zona_techo);

// Evaluar qué pasó con la zona durante la sesión
let resultado = 'sin_reaccion';
let toco_zona = false;
let rompio_zona = false;

for (const vela of values) {
  const low = parseFloat(vela.low);
  const high = parseFloat(vela.high);
  const close = parseFloat(vela.close);

  // ¿Tocó la zona?
  if (high >= precio_suelo && low <= precio_techo) {
    toco_zona = true;
    // ¿Rompió? Cierre fuera de zona con holgura
    if (analisis.direccion_precio === 'alcista' && close > precio_techo * 1.002) {
      rompio_zona = true;
    } else if (analisis.direccion_precio === 'bajista' && close < precio_suelo * 0.998) {
      rompio_zona = true;
    }
  }
}

if (!toco_zona) {
  resultado = 'sin_reaccion';
} else if (rompio_zona) {
  resultado = 'rompio';
} else {
  // Distinguir respeto fuerte vs débil por magnitud de rebote
  const rebote_velas = values.filter(v => {
    const h = parseFloat(v.high); const l = parseFloat(v.low);
    return h >= precio_suelo && l <= precio_techo;
  });
  const max_rebote = Math.max(...rebote_velas.map(v => Math.abs(parseFloat(v.close) - parseFloat(v.open))));
  resultado = max_rebote > (precio_techo - precio_suelo) * 1.5 ? 'respeto_fuerte' : 'respeto_debil';
}

// Determinar sesión actual
const hora = new Date().getUTCHours();
let sesion = 'new_york';
if (hora >= 22 || hora < 8) sesion = 'asia';
else if (hora >= 8 && hora < 13) sesion = 'london';
else if (hora >= 13 && hora < 16) sesion = 'overlap';

const hoy = new Date().toISOString().split('T')[0];

return [{
  json: {
    zonas_historial: {
      fecha: hoy,
      activo: 'XAUUSD',
      timeframe: '1H',
      tipo_zona: analisis.tipo_zona,
      precio_zona_suelo: precio_suelo,
      precio_zona_techo: precio_techo,
      direccion_precio: analisis.direccion_precio,
      resultado,
      sesion
    },
    resultado
  }
}];
